interface Renderer {
    void draw(String shape);
}

// Adaptee: useful, but wrong interface. Cannot be changed (legacy / third-party).
class LegacyPlotter {
    void plotLine(String figure) { /* ... */ }
}

// Adapter: translates. No new behavior, just interface reconciliation.
class PlotterAdapter implements Renderer {
    private final LegacyPlotter plotter;
    PlotterAdapter(LegacyPlotter plotter) { this.plotter = plotter; }
    @Override public void draw(String shape) {
        plotter.plotLine(shape); // translate draw -> plotLine
    }
}

// Decorator: same interface in and out. Adds one behavior, then forwards.
class TimingRenderer implements Renderer {
    private final Renderer inner;
    TimingRenderer(Renderer inner) { this.inner = inner; }
    @Override public void draw(String shape) {
        long t0 = System.nanoTime();
        try {
            inner.draw(shape);
        } finally {
            long dt = System.nanoTime() - t0;
            System.out.println("draw took " + dt + "ns");
        }
    }
}

