from abc import ABC, abstractmethod

# Composite: treat one glyph and a row of glyphs identically.
class Glyph(ABC):
    @abstractmethod
    def draw(self) -> None: ...

class Char(Glyph):
    def __init__(self, c: str): self.c = c
    def draw(self) -> None: print(self.c, end="")

class Row(Glyph):
    def __init__(self): self.children: list[Glyph] = []
    def add(self, g: Glyph): self.children.append(g)
    def draw(self) -> None:
        for ch in self.children: ch.draw()

# Bridge: abstraction (Document) varies independently from implementation (Exporter).
class Exporter(ABC):
    @abstractmethod
    def export(self, text: str) -> None: ...

class Document:
    def __init__(self, exporter: Exporter): self.exporter = exporter
    def save(self, text: str): self.exporter.export(text)  # composition, not subclassing
